CustomField.formula:
IF(TEXT(Picklist_Value__r.Category__c)='Absent',
	IF(Picklist_Value__r.Is_Unexcused__c,'Unexcused Absence','Excused Absence'),
	IF(TEXT(Picklist_Value__r.Category__c)='Partial',
		IF(AND(Picklist_Value__r.Is_Tardy__c,NOT(Picklist_Value__r.Is_Early_Departure__c)),
			IF(Picklist_Value__r.Is_Unexcused__c,'Unexcused Tardy','Excused Tardy'),
			IF(AND(Picklist_Value__r.Is_Early_Departure__c,NOT(Picklist_Value__r.Is_Tardy__c)),
				IF(Picklist_Value__r.Is_Unexcused__c,'Unexcused Early Departure','Excused Early Departure'),
				IF(AND(Picklist_Value__r.Is_Early_Departure__c,Picklist_Value__r.Is_Tardy__c),
					IF(Picklist_Value__r.Is_Unexcused__c,'Unexcused Tardy and Early Departure','Excused Tardy and Early Departure'),
					TEXT(Picklist_Value__r.Category__c)
				)
			)
		),
		IF(OR(ISNULL(TEXT(Picklist_Value__r.Category__c)), ISBLANK(TEXT(Picklist_Value__r.Category__c))),
			'UNKNOWN',
			TEXT(Picklist_Value__r.Category__c)
		)
	)
)
